messages.content:
Write a single self-contained HTML file with a 3D animation using three.js. three.js r160 is available as an ES module at './three.module.js' -- import it with:
  import * as THREE from './three.module.js';
Scene: two cars race on a straight track toward a visible finish line. One car is bright RED, the other bright BLUE. The blue car leads early, then the red car accelerates, overtakes mid-race, and wins. After the red car crosses the finish line the race resets and loops forever. Both cars must be clearly visible and large enough to follow throughout (fill a meaningful part of the frame). Simple ground and sky, camera keeps both cars in view. No external assets besides the three.js import. Output ONLY the HTML in one code block.

response.text:
```html
<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Red vs Blue Race</title>
    <style>
        body { margin: 0; overflow: hidden; background-color: #87CEEB; }
        canvas { display: block; }
    </style>
</head>
<body>
    <script type="module">
        import * as THREE from './three.module.js';

        // --- Configuration ---
        const CONFIG = {
            trackLength: 200,
            trackWidth: 12,
            laneWidth: 3,
            finishLineZ: -90,
            cameraOffset: { x: 0, y: 15, z: 25 },
            cameraLookAhead: 10
        };

        // --- Scene Setup ---
        const scene = new THREE.Scene();
        scene.background = new THREE.Color(0x87CEEB); // Sky Blue
        scene.fog = new THREE.Fog(0x87CEEB, 20, 150);

        const camera = new THREE.PerspectiveCamera(60, window.innerWidth / window.innerHeight, 0.1, 300);
        camera.position.set(CONFIG.cameraOffset.x, CONFIG.cameraOffset.y, CONFIG.cameraOffset.z);

        const renderer = new THREE.WebGLRenderer({ antialias: true });
        renderer.setSize(window.innerWidth, window.innerHeight);
        renderer.shadowMap.enabled = true;
        document.body.appendChild(renderer.domElement);

        // --- Lighting ---
        const ambientLight = new THREE.AmbientLight(0xffffff, 0.6);
        scene.add(ambientLight);

        const dirLight = new THREE.DirectionalLight(0xffffff, 1);
        dirLight.position.set(50, 100, 50);
        dirLight.castShadow = true;
        dirLight.shadow.camera.left = -50;
        dirLight.shadow.camera.right = 50;
        dirLight.shadow.camera.top = 50;
        dirLight.shadow.camera.bottom = -50;
        dirLight.shadow.mapSize.width = 2048;
        dirLight.shadow.mapSize.height = 2048;
        scene.add(dirLight);

        // --- Environment ---
        // Ground
        const groundGeo = new THREE.PlaneGeometry(200, 400);
        const groundMat = new THREE.MeshStandardMaterial({ color: 0x228B22 }); // Forest Green
        const ground = new THREE.Mesh(groundGeo, groundMat);
        ground.rotation.x = -Math.PI / 2;
        ground.position.z = -100;
        ground.receiveShadow = true;
        scene.add(ground);

        // Track
        const trackGeo = new THREE.PlaneGeometry(CONFIG.trackWidth, CONFIG.trackLength + 20);
        const trackMat = new THREE.MeshStandardMaterial({ color: 0x333333 }); // Asphalt
        const track = new THREE.Mesh(trackGeo, trackMat);
        track.rotation.x = -Math.PI / 2;
        track.position.y = 0.05; // Slightly above ground
        track.position.z = -CONFIG.trackLength / 2 + 10;
        track.receiveShadow = true;
        scene.add(track);

        // Finish Line
        const finishGeo = new THREE.PlaneGeometry(CONFIG.trackWidth, 2);
        const finishMat = new THREE.MeshStandardMaterial({ color: 0xffffff }); // White
        const finishLine = new THREE.Mesh(finishGeo, finishMat);
        finishLine.rotation.x = -Math.PI / 2;
        finishLine.position.set(0, 0.06, CONFIG.finishLineZ);
        scene.add(finishLine);

        // Checkered pattern on finish line (simple geometry hack)
        const checkGeo = new THREE.PlaneGeometry(1, 1);
        const checkMat = new THREE.MeshBasicMaterial({ color: 0x000000 });
        for(let x = -CONFIG.trackWidth/2 + 0.5; x < CONFIG.trackWidth/2; x+=2) {
            const check = new THREE.Mesh(checkGeo, checkMat);
            check.rotation.x = -Math.PI / 2;
            check.position.set(x, 0.07, CONFIG.finishLineZ);
            scene.add(check);
        }

        // --- Car Model Factory ---
        function createCar(color) {
            const carGroup = new THREE.Group();

            // Chassis
            const chassisGeo = new THREE.BoxGeometry(2, 0.5, 4);
            const chassisMat = new THREE.MeshStandardMaterial({ color: color });
            const chassis = new THREE.Mesh(chassisGeo, chassisMat);
            chassis.position.y = 0.5;
            chassis.castShadow = true;
            carGroup.add(chassis);

            // Cabin
            const cabinGeo = new THREE.BoxGeometry(1.8, 0.4, 2);
            const cabinMat = new THREE.MeshStandardMaterial({ color: 0x111111 }); // Dark glass
            const cabin = new THREE.Mesh(cabinGeo, cabinMat);
            cabin.position.set(0, 1, -0.2);
            cabin.castShadow = true;
            carGroup.add(cabin);

            // Spoiler
            const spoilerGeo = new THREE.BoxGeometry(2.2, 0.1, 0.5);
            const spoiler = new THREE.Mesh(spoilerGeo, chassisMat);
            spoiler.position.set(0, 1.2, 1.8);
            carGroup.add(spoiler);

            const spoilerLegsGeo = new THREE.BoxGeometry(0.1, 0.4, 0.1);
            const leg1 = new THREE.Mesh(spoilerLegsGeo, chassisMat);
            leg1.position.set(0.8, 1, 1.8);
            carGroup.add(leg1);
            const leg2 = new THREE.Mesh(spoilerLegsGeo, chassisMat);
            leg2.position.set(-0.8, 1, 1.8);
            carGroup.add(leg2);

            // Wheels
            const wheelGeo = new THREE.CylinderGeometry(0.4, 0.4, 0.3, 16);
            const wheelMat = new THREE.MeshStandardMaterial({ color: 0x111111 });
            const wheelPositions = [
                { x: 1.1, y: 0.4, z: 1.2 },
                { x: -1.1, y: 0.4, z: 1.2 },
                { x: 1.1, y: 0.4, z: -1.2 },
                { x: -1.1, y: 0.4, z: -1.2 }
            ];

            wheelPositions.forEach(pos => {
                const wheel = new THREE.Mesh(wheelGeo, wheelMat);
                wheel.rotation.z = Math.PI / 2;
                wheel.position.set(pos.x, pos.y, pos.z);
                wheel.castShadow = true;
                carGroup.add(wheel);
            });

            return carGroup;
        }

        const redCar = createCar(0xff0000);
        const blueCar = createCar(0x0000ff);

        // Position cars
        redCar.position.set(CONFIG.laneWidth, 0, 10); // Right lane
        blueCar.position.set(-CONFIG.laneWidth, 0, 10); // Left lane

        scene.add(redCar);
        scene.add(blueCar);

        // --- Race Logic ---
        let raceTime = 0;
        const raceDuration = 10; // Seconds for the full race
        let isRacing = true;
        let resetTimer = 0;

        function resetRace() {
            raceTime = 0;
            isRacing = true;
            redCar.position.z = 10;
            blueCar.position.z = 10;
            redCar.rotation.set(0, 0, 0);
            blueCar.rotation.set(0, 0, 0);
        }

        // --- Animation Loop ---
        const clock = new THREE.Clock();

        function animate() {
            requestAnimationFrame(animate);

            const delta = clock.getDelta();
            const time = clock.getElapsedTime();

            if (isRacing) {
                raceTime += delta;

                // Progress 0 to 1
                let p = Math.min(raceTime / raceDuration, 1);

                // Blue Car: Leads early, then slows
                // Using a curve that peaks early
                let blueZ = 10 - (CONFIG.trackLength - 20) * (1 - Math.pow(1 - p, 2.5)); 

                // Red Car: Slower start, accelerates hard
                // Using a curve that is flat then steep
                let redZ = 10 - (CONFIG.trackLength - 20) * Math.pow(p, 1.8);

                blueCar.position.z = blueZ;
                redCar.position.z = redZ;

                // Add some visual vibration/speed effect
                blueCar.position.y = Math.sin(time * 20) * 0.05;
                redCar.position.y = Math.sin(time * 25) * 0.05;

                // Check finish
                if (redCar.position.z <= CONFIG.finishLineZ) {
                    isRacing = false;
                    resetTimer = 2; // 2 seconds pause before reset
                }
            } else {
                // Reset logic
                resetTimer -= delta;
                if (resetTimer <= 0) {
                    resetRace();
                }
            }

            // Camera Logic
            // Find the leading car
            const leadZ = Math.min(redCar.position.z, blueCar.position.z);

            // Camera follows behind the lead car, but stays in the middle of the track
            // Smooth lerp
            const targetCamZ = leadZ + CONFIG.cameraOffset.z;
            camera.position.z += (targetCamZ - camera.position.z) * 0.1;

            // Keep camera height and x constant
            camera.position.x = CONFIG.cameraOffset.x;
            camera.position.y = CONFIG.cameraOffset.y;

            // Look ahead of the lead car
            camera.lookAt(0, 2, leadZ - CONFIG.cameraLookAhead);

            renderer.render(scene, camera);
        }

        // Handle window resize
        window.addEventListener('resize', () => {
            camera.aspect = window.innerWidth / window.innerHeight;
            camera.updateProjectionMatrix();
            renderer.setSize(window.innerWidth, window.innerHeight);
        });

        animate();
    </script>
</body>
</html>
```
